SELECT CAST(DATE_FORMAT(CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE), '%Y-%m-01') AS DATE), AVG(DATEDIFF(CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE), CAST(s.shipped_at_utc + INTERVAL 6 HOUR AS DATE))) FROM shipments s WHERE s.delivered_at_utc IS NOT NULL AND s.order_id IN (SELECT order_id FROM orders WHERE is_deleted = FALSE) AND CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE) >= DATE '2025-07-01' AND CAST(s.delivered_at_utc + INTERVAL 6 HOUR AS DATE) <= DATE '2026-06-30' GROUP BY 1 ORDER BY 1
